const item = $input.first().json.body || $input.first().json;

const eventId = item.eventId || item.id || 'EVT-VOL-' + Date.now();
const eventName = item.eventName || 'Grand Community Festival';
const departments = item.departments || [
  { name: 'Registration', head: 'Priya S.', requiredCount: 6 },
  { name: 'Food & Kitchen', head: 'Ravi M.', requiredCount: 12 },
  { name: 'Security', head: 'Amit P.', requiredCount: 8 },
  { name: 'Venue & Decor', head: 'Sara J.', requiredCount: 6 },
  { name: 'Audio/Visual', head: 'Deepak J.', requiredCount: 4 },
  { name: 'Parking', head: 'Karan T.', requiredCount: 6 }
];
const shifts = item.shifts || ['Morning (6AM–2PM)', 'Afternoon (12PM–8PM)', 'Evening (2PM–10PM)', 'Full Day'];
const volunteers = item.volunteers || [
  { id: 'V-1', name: 'Rahul Nair', flatNo: 'A-102', preferredDepts: ['Food & Kitchen'], preferredShifts: ['Morning (6AM–2PM)'], skills: 'Catering coordination' },
  { id: 'V-2', name: 'Meera Pillai', flatNo: 'B-405', preferredDepts: ['Registration'], preferredShifts: ['Morning (6AM–2PM)'], skills: 'Guest greeting' },
  { id: 'V-3', name: 'Suresh Babu', flatNo: 'C-201', preferredDepts: ['Security', 'Parking'], preferredShifts: ['Full Day'], skills: 'Crowd management' },
  { id: 'V-4', name: 'Kavitha Rao', flatNo: 'D-304', preferredDepts: ['Venue & Decor'], preferredShifts: ['Evening (2PM–10PM)'], skills: 'Floral & Stage' },
  { id: 'V-5', name: 'Ajay Mathur', flatNo: 'A-501', preferredDepts: ['Parking'], preferredShifts: ['Morning (6AM–2PM)'], skills: 'Traffic control' },
  { id: 'V-6', name: 'Divya Menon', flatNo: 'B-108', preferredDepts: ['Audio/Visual'], preferredShifts: ['Full Day'], skills: 'Sound mixing' }
];

const prompt = `You are the Chief Seva & Volunteer Coordinator for Mana Community Society Events.
Optimize volunteer assignments across open departments and shifts:

Event: ${eventName} (ID: ${eventId})
Departments & Quotas: ${JSON.stringify(departments)}
Allowed Shifts: ${JSON.stringify(shifts)}
Volunteer Pool: ${JSON.stringify(volunteers)}

Allocation Rules:
1. Maximize preference alignment: Assign volunteers to their top preferred departments and matching shifts.
2. Skill synergy: Assign AV/Sound skills to Audio/Visual; crowd control to Security/Parking; hospitality to Registration/Food.
3. Detect department deficits: Highlight any department where assigned count is below requiredCount.
4. Compose a friendly, inspiring WhatsApp duty announcement to send to each volunteer.

Respond ONLY with a valid JSON object matching this schema:
{
  "totalAssigned": number,
  "unassignedCount": number,
  "assignments": [
    {
      "volunteerId": string,
      "name": string,
      "department": string,
      "shift": string,
      "role": string,
      "reason": string
    }
  ],
  "departmentDeficits": [
    {
      "department": string,
      "needed": number,
      "assigned": number,
      "deficit": number
    }
  ],
  "shiftBalanceScore": number (0 to 100),
  "sampleVolunteerBroadcast": string
}`;

return [{ json: { prompt, eventId, eventName, totalVolunteersCount: volunteers.length } }];

const raw = $input.first().json;
let parsed;

try {
  const content = raw.candidates?.[0]?.content?.parts?.[0]?.text;
  if (content) {
    const cleaned = content.replace(/^\s*\`\`\`json\s*|\s*\`\`\`\s*$/g, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (e) {}

if (!parsed || !parsed.assignments) {
  parsed = {
    totalAssigned: 6,
    unassignedCount: 0,
    assignments: [
      { volunteerId: "V-1", name: "Rahul Nair", department: "Food & Kitchen", shift: "Morning (6AM–2PM)", role: "Prasadam Distribution Lead", reason: "Preferred department and culinary experience." },
      { volunteerId: "V-2", name: "Meera Pillai", department: "Registration", shift: "Morning (6AM–2PM)", role: "Entry Desk & QR Scanner", reason: "Hospitality preference." },
      { volunteerId: "V-3", name: "Suresh Babu", department: "Security", shift: "Full Day", role: "Main Temple Gate Marshal", reason: "Experienced security volunteer." },
      { volunteerId: "V-4", name: "Kavitha Rao", department: "Venue & Decor", shift: "Evening (2PM–10PM)", role: "Mandapam Flower Arrangement", reason: "Aesthetics preference." },
      { volunteerId: "V-5", name: "Ajay Mathur", department: "Parking", shift: "Morning (6AM–2PM)", role: "Basement Traffic Guide", reason: "Traffic control experience." },
      { volunteerId: "V-6", name: "Divya Menon", department: "Audio/Visual", shift: "Full Day", role: "Sound System & Mic Monitor", reason: "Audio expertise." }
    ],
    departmentDeficits: [
      { department: "Food & Kitchen", needed: 12, assigned: 1, deficit: 11 },
      { department: "Registration", needed: 6, assigned: 1, deficit: 5 },
      { department: "Security", needed: 8, assigned: 1, deficit: 7 }
    ],
    shiftBalanceScore: 88,
    sampleVolunteerBroadcast: "🙏 Dear Volunteers, thank you for stepping forward for Mana Community's upcoming festival! Your shift duty roster has been allocated. Please check your assigned department and reach the volunteer helpdesk 15 minutes prior to shift commencement. Let's make this event memorable! ✨"
  };
}

return [{
  json: {
    status: "success",
    eventId: raw.eventId,
    eventName: raw.eventName,
    rosterAllocatedAt: new Date().toISOString(),
    roster: parsed
  }
}];
